const raw = $json.text ?? $json.output ?? '';
const src = $('Memory Input').first().json;
let d;
try {
  const a = raw.indexOf('{'), b = raw.lastIndexOf('}');
  d = JSON.parse(raw.slice(a, b + 1));
} catch (e) {
  // Extraction failed: send NO structure so the API's built-in extractor still runs.
  return { json: { agent: src.agent, text: src.text, importance: src.importance, structured: false } };
}
const str = v => (v === undefined || v === null) ? '' : String(v).trim();
const entities = (d.entities || []).filter(e => str(e.name)).map(e => [str(e.name), str(e.type)]);
const relations = (d.relations || []).filter(r => str(r.src) && str(r.dst))
  .map(r => [str(r.src), str(r.kind) || 'related_to', str(r.dst)]);
const facts = (d.facts || []).filter(f => str(f.subject) && str(f.predicate) && f.value !== undefined && str(f.value))
  .map(f => [str(f.subject), str(f.predicate), str(f.value)]);
return { json: { agent: src.agent, text: src.text, importance: src.importance, structured: true, entities, relations, facts } };
